import{_ as o,l as s,o as e,c as n,v as t,p as E,x as r,d as l,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"主动份额","description":"","frontmatter":{"title":"主动份额","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/active-share.md","filePath":"quant/active-share.md","lastUpdated":1789023840000}'),A={name:"quant/active-share.md"};function B(c,a,p,u,m,_){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="主动份额" tabindex="-1">主动份额 <a class="header-anchor" href="#主动份额" aria-label="Permalink to &quot;主动份额&quot;">​</a></h1><div class="epigraph"><p>跟踪误差度量的是收益偏离的波动；主动份额度量的是持仓与基准的重量差。可以高 TE 低主动份额（杠杆因子赌注），也可以低 TE 高主动份额（对冲掉的选股）。</p><footer>—— Cremers and Petajisto, How Active Is Your Fund Manager? A New Measure That Predicts Performance, Review of Financial Studies, 2009</footer></div><p><a href="/quant/benchmark-tracking-error">上一课</a>把契约钉在 TE 上。主动份额（active share）的缺口是<strong>持仓层的偏离</strong>：\\(\\tfrac12\\sum_i|w_{p,i}-w_{b,i}|\\)。Cremers–Petajisto 用它区分橱窗指数（closet indexer）与真正主动。本课写它与 TE、与 <a href="/quant/brinson">Brinson</a> 的分工，以及它<strong>不</strong>保证 alpha——高主动份额也可以是分散很差的错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 可来自几只期货或行业倾斜，持仓仍与指数高度重叠。主动份额高意味着名字层面不同，但可以用空头或对冲把 TE 压低（多空）。问题是产品识别：收主动费却主动份额接近零，是契约问题；主动份额高却持续负 IR，是技能问题。Petajisto 后续把基金分成因子赌注 vs 选股。不要把主动份额当新的定价因子去对 <a href="/quant/capm">CAPM</a> 回归；它是治理度量。</p><p>与 130/30：空头增加主动份额，也增加借券。与股票多空中性：相对现金的主动份额无定义，应相对对冲基准或零。</p><h3 id="基准一换-份额就变" tabindex="-1">基准一换，份额就变 <a class="header-anchor" href="#基准一换-份额就变" aria-label="Permalink to &quot;基准一换，份额就变&quot;">​</a></h3><p>用错基准会把风格暴露当成主动份额（小盘基金对标普 500）。必须与 TE 课同一套可投资基准。衍生品、空头、未分类现金要有处理规则，否则一半份额只是会计。</p><p><span class="marginnote">Cremers–Petajisto 的预测力在后续样本有争议。即便预测力减弱，橱窗指数识别仍然有用：那是费用是否该收主动价的证据，不必依赖 alpha 预测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计算：持仓与基准权重对齐到同一分类与时点。分解：行业内 vs 行业间（接近 Brinson 配置/选择）。对照：主动份额 vs 事后 TE vs 净 IR。阈值：极低则疑为橱窗；极高则查集中度与容量。ETF 化的因子产品主动份额可以高，那是规则暴露，不是选股。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>委托需要同时看「离基准多远」（份额）和「收益晃多厉害」（TE）。两者一起才能分清：在复制、在赌因子、还是在选股。费用应匹配真实主动；生命周期里，拥挤策略的主动份额可以仍高，IR 已经没了。</p>',13)),(e(),E(h,null,{default:r(()=>[d(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E5%B7%AE%E7%BB%9D%E5%AF%B9%E5%80%BC%22%5D%20--%3E%20AS%5B%22%E4%B8%BB%E5%8A%A8%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20R%5B%22%E4%B8%BB%E5%8A%A8%E6%94%B6%E7%9B%8A%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20TE%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20AS%20--%3E%20Closet%5B%22%E4%BD%8E%E4%BB%BD%E9%A2%9D%20%E6%A9%B1%E7%AA%97%E6%8C%87%E6%95%B0%22%5D%0A%20%20TE%20--%3E%20Factor%5B%22%E9%AB%98%20TE%20%E6%88%96%E4%B8%BA%E5%9B%A0%E5%AD%90%E6%9D%A0%E6%9D%86%22%5D%0A%20%20AS%20--%3E%20Stock%5B%22%E9%AB%98%E4%BB%BD%E9%A2%9D%20%E9%80%89%E8%82%A1%E6%88%96%E9%9B%86%E4%B8%AD%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>持仓披露滞后使实时主动份额不可得。对冲基金不披露持仓时，度量退回 TE 与因子暴露。下一课改收益会计：即使持仓主动，现金流也会改写「赚了多少」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主动份额是持仓偏离，TE 是收益偏离，二者不可替代。</li><li>用途首先是识别橱窗指数与费用是否匹配。</li><li>高份额不蕴含正 IR，须与集中度和成本一起看。</li><li>出处：Cremers and Petajisto, <em>RFS</em>, 2009；Petajisto 对因子赌注 vs 选股的分类。</li></ul>',4))])}const D=o(A,[["render",B]]);export{f as __pageData,D as default};
